/**
 * ✅ 단원 자동 인식 (강화)
 * 우선순위: ?unit=physics_XX → 파일명 physics_XX.html → 제목 숫자
 * ⚠️ HTML에서 이미 CUR_UNIT 설정했으면 덮어쓰지 않음
 */
(function () {
  // 이미 설정된 CUR_UNIT이 있고, physics_로 시작하면 덮어쓰지 않음
  if (window.CUR_UNIT && window.CUR_UNIT.startsWith('fit_physics_')) {
    console.log('[fit_physics_content.js] CUR_UNIT 이미 설정됨:', window.CUR_UNIT);
    return;
}

  const qs = new URLSearchParams(location.search).get('unit');
  let unit = null;

  if (qs) {
    const m = qs.toLowerCase().match(/fit_physics[_-]?(\d{1,2})/);
    if (m) unit = `fit_physics_${m[1].padStart(2, '0')}`;
}

  if (!unit) {
    const m2 = location.pathname.toLowerCase().match(/fit_physics[_-]?(\d{1,2})\.html/);
    if (m2) unit = `fit_physics_${m2[1].padStart(2, '0')}`;
}

  if (!unit && document.title) {
    const m3 = document.title.match(/(\d{1,2})/);
    if (m3) unit = `fit_physics_${m3[1].padStart(2, '0')}`;
}

  window.CUR_UNIT = unit || 'fit_physics_01';
})();

