      q4:'정답: ②번. 본문에서 소리의 속도가 공기에서 340m/s, 물에서 1,500m/s라고 했으므로, 물에서 약 4배 더 빠르게 이동합니다.<br><br>[오답 풀이]<br>① 소리는 진공에서도 빠르게 전달된다 → 소리는 매질이 필요하므로 진공에서는 전달되지 않습니다.<br>③ 진동수가 낮을수록 높은음이 난다 → 진동수가 높을수록 높은음이 납니다. 진동수가 낮으면 낮은음이 납니다.<br>④ 메아리는 소리가 흡수되어 사라지는 현상이다 → 메아리는 소리가 벽이나 산에 부딪혀 반사되어 되돌아오는 현상입니다.'
