      q4:'정답: ③번. 보온병은 이중벽 사이의 진공층으로 전도와 대류를 차단하고, 반사면으로 복사도 막아 온도를 유지합니다.<br><br>[오답 풀이]<br>① 열은 온도가 낮은 곳에서 높은 곳으로 자연스럽게 이동한다 → 열은 온도가 높은 곳에서 낮은 곳으로 이동합니다.<br>② 냄비 손잡이를 금속으로 만들면 열전도가 잘 되어 편리하다 → 냄비 손잡이를 금속으로 만들면 열전도가 잘 되어 손을 데일 수 있습니다. 손잡이는 열전도가 잘 안 되는 재료로 만들어야 합니다.<br>④ 태양열은 대류를 통해 지구에 도달한다 → 태양열은 복사를 통해 진공인 우주 공간을 지나 지구에 도달합니다. 대류는 물질이 있어야 가능합니다.'
