      q1:'정답: ③번. 에너지 보존 법칙에 따르면 에너지는 새로 생기거나 없어지지 않고 형태만 바뀌므로, "새로 생기거나 완전히 사라질 수 있다"는 글과 일치하지 않습니다.<br><br>[오답 풀이]<br>① 에너지에는 운동 에너지, 위치 에너지, 열에너지, 전기 에너지, 화학 에너지 등 여러 형태가 있다 → 본문 내용과 일치합니다.<br>② 에너지는 한 형태에서 다른 형태로 바뀔 수 있으며, 이를 에너지 전환이라고 한다 → 본문 내용과 일치합니다.<br>④ 태양광 발전은 태양의 빛에너지를 전기 에너지로 바꾸는 방식이다 → 본문 내용과 일치합니다.',
