      q4:'정답: ②번. 스키는 면적이 넓어서 체중이 분산되고, 단위 면적당 압력이 작아져서 눈에 잘 빠지지 않습니다.<br><br>[오답 풀이]<br>① 철로 만든 배가 뜨는 이유는 철이 물보다 가볍기 때문이다 → 철 배가 뜨는 이유는 빈 공간이 많아 전체 부피가 크고 큰 부력을 받기 때문입니다.<br>③ 물속 깊이 내려갈수록 수압이 작아진다 → 물속 깊이 내려갈수록 수압이 커집니다.<br>④ 풍선이 높은 곳에서 터지는 이유는 기압이 높아지기 때문이다 → 높은 곳으로 올라갈수록 기압이 낮아져서 풍선 내부 압력이 상대적으로 커지면서 터집니다.'
