      q4:'정답: ②번. 문어발식 콘센트 사용은 과부하로 인해 전선이 과열되어 화재 위험이 있습니다.<br><br>[오답 풀이]<br>① 퓨즈는 과전류가 흐르면 더 많은 전류를 흘려 화재를 진압한다 → 퓨즈는 과전류가 흐르면 녹아서 회로를 끊어 화재를 방지합니다.<br>③ 젖은 손은 저항이 높아져서 감전 위험이 낮다 → 젖은 손은 저항이 낮아져서 감전 위험이 더 높습니다.<br>④ 피복이 벗겨진 전선은 그냥 두어도 안전하다 → 피복이 벗겨진 전선은 합선의 원인이 되어 화재 위험이 있으므로 즉시 교체해야 합니다.'
