    passage: [
      '20세기 초까지 물리학은 뉴턴 역학으로 세상의 거의 모든 운동을 설명할 수 있다고 믿었다. 그러나 원자보다 작은 세계로 눈을 돌리는 순간, 그 믿음은 흔들리기 시작하였다. 빛이 입자와 파동의 성질을 동시에 가진다는 점, 전자의 위치와 속도를 동시에 정확히 알 수 없다는 점이 잇따라 밝혀지면서 새로운 물리학이 필요해졌다. 1900년 플랑크가 빛 에너지가 작은 덩어리 단위로만 주고받아진다는 사실을 제시한 것이 그 시작점이 되었고, 이후 보어·하이젠베르크·슈뢰딩거 같은 학자들이 이론을 다듬어 갔다. 그 결과 태어난 학문이 바로 <b>양자역학</b>이다. 양자역학은 원자·전자·빛처럼 매우 작은 세계가 일상의 직관과는 다른 규칙을 따른다는 점을 수학적으로 설명한다. 이 학문은 단순한 이론에 머물지 않고, 오늘날 우리가 사용하는 스마트폰·반도체·의료 기기의 기반을 이루는 가장 실용적인 물리학으로 자리 잡았다.',
      '양자역학의 핵심 개념 중 하나가 <b>에너지 준위</b>이다. 원자 속 전자는 아무 에너지나 가질 수 있는 것이 아니라, 정해진 몇몇 \"계단\" 같은 값만 가질 수 있다. 전자는 에너지를 흡수해 더 높은 준위로 뛰어오르거나, 빛을 내보내며 낮은 준위로 내려온다. 이러한 원리가 가장 적극적으로 활용되는 분야가 <b>반도체</b>이다. 반도체는 도체와 부도체의 중간 성질을 지닌 물질로, 외부 신호에 따라 전류를 통하게 하거나 막을 수 있다. 실리콘 결정에 인이나 붕소 같은 다른 원소를 아주 적은 양 섞어 주면 전자의 흐름을 정밀하게 조절할 수 있게 된다. 트랜지스터·메모리·CPU 같은 모든 전자 장치는 결국 수많은 반도체 소자가 \"켜짐\"과 \"꺼짐\"을 정밀하게 반복하며 작동하는 원리이다.',
      '<b>LED</b>와 <b>레이저</b>는 양자역학이 만들어 낸 가장 일상적인 빛이다. LED는 전자가 높은 준위에서 낮은 준위로 떨어질 때 그 차이만큼의 에너지를 빛으로 내놓는 원리로 작동한다. 그래서 같은 전기로도 백열전구보다 훨씬 효율적으로 빛을 만들 수 있고, 색상도 정확히 제어할 수 있다. 청색 LED를 개발한 일본 연구진이 2014년 노벨 물리학상을 받은 일은 이 작은 빛이 세상에 끼친 영향을 잘 보여 준다. 레이저는 한 단계 더 나아가 같은 진동수와 같은 방향의 빛 입자가 동시에 쏟아져 나오도록 한 빛이다. 그 결과 매우 강하고 좁은 빔이 만들어져 광디스크 읽기·정밀 절단·시력 교정 수술·통신용 광섬유 등에 두루 활용된다. 같은 원리가 응용되는 곳마다 우리의 일상은 한층 정밀해지고 편리해진다.',
      '오늘날 양자역학은 미래 기술의 가장 뜨거운 무대로 떠오르고 있다. <b>양자컴퓨터</b>는 기존 컴퓨터가 한 번에 \"0 또는 1\" 하나만 다루는 것과 달리, 양자 중첩 원리를 활용해 \"0과 1을 동시에\" 다루어 매우 복잡한 계산을 훨씬 빠르게 풀 수 있다. 양자 통신은 도청이 사실상 불가능한 안전한 통신을 가능하게 하고, 양자 센서는 자기장·중력의 미세한 변화까지 감지한다. 우리나라도 양자 분야에 투자를 시작하였고, 주요 나라들이 양자 패권 경쟁을 벌이고 있다. 이러한 기술은 빠르게 발전 중이지만, 양자 시스템의 안정성과 비용 등 풀어야 할 과제도 많다. 양자 기술이 사회에 자리 잡으려면 과학자뿐 아니라 시민도 그 원리와 활용 방향을 이해하는 자세가 함께 필요하다.'
    ],
